-- ISGH seed (client #1, the founding client) – run once per environment AFTER the migrations, as the database owner:
--   psql "$DATABASE_URL" -v ON_ERROR_STOP=1 -f sql/seed/isgh.sql
-- Idempotent (ON CONFLICT DO NOTHING / UPDATE). Real masjids from isgh.org/islamic-centers (read 17 Oct 2026); four names
-- are marked "to confirm" and the ISGH Main Center (Eastside office) is kind 'office' until ISGH confirms it.
-- Each masjid serves its own ZIP for now – the full ZIP list per zone comes from the Zones map (KML) the client will send.
-- Membership plans = "ISGH today (isgh.org, 2026)": Check-o-matic, Individual $20, Lifetime Individual $1,000, Lifetime Family $1,500.
BEGIN;
VALUES ('isgh', 'Islamic Society of Greater Houston', 'ISGH', 'society', true, 1, 'network', 'active', 'annual', '2026-09-01', 'America/Chicago', 'US', 'TX', 'Houston', '3110 Eastside St, Houston, TX 77098', '', '', 'bylaws-society', 'member-web.nextgrow.pro', 'member-admin.nextgrow.pro')
ON CONFLICT (slug) DO UPDATE SET client_no = 1, founding = true, legacy_web_host = EXCLUDED.legacy_web_host, legacy_admin_host = EXCLUDED.legacy_admin_host;
  SELECT 'Seed', 'Organization created', id, 'ISGH joined as client #1 – the founding client' FROM platform.organizations WHERE slug = 'isgh'
  AND NOT EXISTS (SELECT 1 FROM platform.audit a JOIN platform.organizations o ON o.id = a.org_id WHERE o.slug = 'isgh' AND a.action = 'Organization created');



SELECT g.id, p.id, p.name, p.cat, p.term, 1, p.cents, p.hh, true, p.sort FROM platform.organizations g, (VALUES
  ('checkomatic', 'Check-o-matic (Primary and Spouse)', 'Checkomatic', 'monthly', 4000, 2, 1),
  ('individual', 'Individual', 'Individual', 'year', 2000, 1, 2),
  ('lifetime-individual', 'Lifetime (Individual)', 'Lifetime', 'lifetime', 100000, 1, 3),
  ('lifetime-family', 'Lifetime (Family – Primary and Spouse)', 'Lifetime', 'lifetime', 150000, 2, 4)
) AS p(id, name, cat, term, cents, hh, sort) WHERE g.slug = 'isgh' ON CONFLICT (org_id, id) DO NOTHING;
) AS f(id, name, kind) WHERE g.slug = 'isgh' ON CONFLICT (org_id, id) DO NOTHING;
COMMIT;

-- B6b: ISGH's member IDs are HOU-123456 – a setting of the organization, not a constant
UPDATE platform.organizations SET member_prefix = 'HOU' WHERE slug = 'isgh' AND member_prefix = '';
